def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tallies of opponent's reactions conditioned on our previous action.
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    opp_c = 0
    for mine, opp in history:
        if opp == 'C':
            opp_c += 1
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    remaining = 100 - n
    last_me, last_opp = history[-1]
    coop_rate = opp_c / n

    # Very short history: open cooperatively but retaliate immediately on a defection.
    if n <= 2:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Endgame: squeeze value. Against likely cooperators defect; against
    # relentless defectors defecting is also safest (1 vs 0).
    if remaining <= 3:
        return 'D'

    # Long-run exploitation of a nearly unconditional cooperator, but keep
    # enough cooperation that we do not destroy the relationship too early.
    if coop_rate > 0.9 and n >= 10:
        if remaining <= 15:
            return 'D'
        if rng.random() < 0.15:
            return 'D'
        return 'C'

    # Pure defector: cut losses.
    if coop_rate < 0.15:
        return 'D'

    # Conditional cooperation probabilities.
    after_c = cc / (cc + cd) if (cc + cd) > 0 else 0.5
    after_d = dc / (dc + dd) if (dc + dd) > 0 else 0.5

    # Opponent appears forgiving (cooperated after our defection).
    forgiving = after_d > 0.5

    # Opponent is a consistent retaliator (rarely cooperates after our D).
    retaliatory = after_d < 0.2 and (dc + dd) >= 3

